import { SearchRepository } from './SearchRepository'
import { toSearchResult, type SearchResult } from './mapper'

export class SearchService {
  constructor(private readonly repo: SearchRepository) {}

  async search(query: string, limit = 20): Promise<SearchResult[]> {
    const products = await this.repo.findByText(query, limit)
    // #901: results now carry their tags for the chips in the UI.
    return Promise.all(products.map(async (product) => toSearchResult(product, await product.getTags())))
  }
}

import { Product, Tag } from '../db/models'
import { Op, literal } from 'sequelize'

export class SearchRepository {
  findByText(query: string, limit: number) {
    return Product.findAll({
      attributes: ['id', 'name', 'priceCents', 'brandId', [literal(`ts_rank(search_vector, plainto_tsquery('english', :q))`), 'rank']],
      where: { [Op.and]: [literal(`search_vector @@ plainto_tsquery('english', :q)`), { archivedAt: null }] },
      replacements: { q: query },
      order: [[literal('rank'), 'DESC']],
      limit,
    })
  }
}

export function SearchBox({ onSearch }: { onSearch: (q: string) => void }) {
  const [value, setValue] = useState('')
  // Debounced so typing "wireless headphones" doesn't fire 19 requests.
  const debounced = useDebouncedCallback(onSearch, 250)
  return <input value={value} onChange={(e) => { setValue(e.target.value); debounced(e.target.value) }} placeholder="Search products" />
}

// Search analytics: fire-and-forget, never on the request's critical path.
export function trackSearch(query: string, resultCount: number, latencyMs: number) {
  queueMicrotask(() => analytics.track('search.performed', { query, resultCount, latencyMs }))
}

