export function cartTotal(items: CartItem[]): number {
  // Round each line, not the total: matches what the payment provider charges.
  return items.reduce((sum, i) => sum + Math.round(i.priceCents * i.quantity), 0)
}

export function BrandFilter({ brands, selected, onChange }: Props) {
  return (
    <select value={selected ?? ''} onChange={(e) => onChange(e.target.value || null)}>
      <option value="">All brands</option>
      {brands.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
    </select>
  )
}
